  levelBurst(g,i){if(g.levelUpTimer[i]<=0)return;const s=g.size[i]*(1.5+(2.2-g.levelUpTimer[i])*.7),gold=[1,.88,.2];for(let n=0;n<12;n++){const a=n*Math.PI/6,x=g.x[i]+Math.cos(a)*s,z=g.z[i]+Math.sin(a)*s,y=g.y[i]+Math.sin(g.time*5+n)*.25;this.tri([x,y-.18,z],[x,y+.35,z],[x+Math.cos(a)*.16,y,z+Math.sin(a)*.16],gold)}}
