  render(g,width,height){this.data.length=0;const floor=-61;for(let x=-90;x<90;x+=30)for(let z=-90;z<90;z+=30){const c=((x+z)/30&1)?[.08,.27,.27]:[.07,.23,.25];this.quad([x,floor,z],[x,floor,z+30],[x+30,floor,z+30],[x+30,floor,z],c)}for(const o of g.obstacles)this.rock(...o);for(let n=0;n<55;n++){const a=n*2.399,d=12+(n*17)%76,x=Math.cos(a)*d,z=Math.sin(a)*d,y=-60+((n*7)%9)*.35;this.plant(x,y,z,1.5+(n%5)*.7,g.time*.7+n)}for(let i=0;i<g.capacity;i++)if(g.alive[i]){if(g.kind[i]===KIND.FISH){this.fish(g,i);this.levelBurst(g,i)}else if(g.kind[i]===KIND.MEAT)this.meat(g,i);else this.rock(g.x[i],g.y[i],g.z[i],g.size[i]*.65)}const gl=this.gl,cam=g.camera;gl.disable(gl.SCISSOR_TEST);gl.viewport(0,0,width,height);gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.enable(gl.CULL_FACE);gl.cullFace(gl.BACK);gl.clearColor(.01,.11,.19,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(this.program);const vp=mul(perspective(cam.fov*Math.PI/180,width/height,.08,240),lookAt([cam.x,cam.y,cam.z],[cam.tx,cam.ty,cam.tz]));gl.uniformMatrix4fv(this.vp,false,vp);gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);const arr=new Float32Array(this.data);gl.bufferData(gl.ARRAY_BUFFER,arr,gl.DYNAMIC_DRAW);gl.enableVertexAttribArray(this.pos);gl.vertexAttribPointer(this.pos,3,gl.FLOAT,false,24,0);gl.enableVertexAttribArray(this.color);gl.vertexAttribPointer(this.color,3,gl.FLOAT,false,24,12);gl.drawArrays(gl.TRIANGLES,0,arr.length/6);this.stats.vertices=arr.length/6;this.stats.triangles=this.stats.vertices/3;this.stats.drawCalls=1;return this.stats}
  hud(g){const s=g.snapshot(),p=s.player;if(!p)return['사망 — 몸이 고기 조각으로 남았습니다','R 키로 다시 시작'];const region=REGIONS.reduce((a,b)=>Math.hypot(g.x[g.player]-b.center[0],g.z[g.player]-b.center[2])<Math.hypot(g.x[g.player]-a.center[0],g.z[g.player]-a.center[2])?b:a,REGIONS[0]),level=g.levelUpTimer[g.player]>0?`★ LEVEL UP!  Lv.${p.level} ★`:'';return[level,`${p.species}  Lv.${p.level}   HP ${Math.ceil(p.hp)}/${Math.ceil(p.maxHp)}`,`성장 ${Math.floor(p.xp)} / ${p.nextXp}   크기 ${p.size.toFixed(2)}m   ${region.name}`,`WASD 이동 · Space/C 상승/하강 · Shift 질주 · 마우스/방향키 조준 · 클릭/E 물기`,`${s.fish} fish · ${s.food} food · ${s.grid.cells} cells · ${STATE_NAME[g.state[g.player]]||'PLAYER'}`].filter(Boolean)}
